/**
 * model-outputs-loader.js
 * Loads real model_outputs.json (generated by train_and_export_models.py)
 * and injects live model data into the SAS Viya Visual Analytics dashboard.
 *
 * This replaces hardcoded values with real trained model predictions.
 */

const ModelOutputs = {
    data: null,
    loaded: false,

    /**
     * Fetches model_outputs.json from the server
     */
    async load() {
        try {
            const resp = await fetch('model_outputs.json');
            if (!resp.ok) {
                console.warn('[ModelOutputs] model_outputs.json not found, using embedded data.');
                return false;
            }
            this.data = await resp.json();
            this.loaded = true;

            // Dynamically inject real trained model odds ratios and BCa intervals into SAS_DATA
            if (window.SAS_DATA && Array.isArray(window.SAS_DATA.triAxial)) {
                const m1_coefs = this.data.model1_ordinal_salary?.coefficients || {};
                const m2_skills = this.data.model2_jds_hike?.skill_odds_ratios || {};

                const keyMap = {
                    'big_data': { m1: 'flag_big_data', m2: 'big_data_skills' },
                    'maths_stats': { m1: 'flag_maths_stats', m2: 'maths-stats_skills' },
                    'core_coding': { m1: 'flag_core_coding', m2: 'coding_skills' },
                    'ai_ml': { m1: 'flag_ai_ml', m2: 'ai_and_ml_skills' },
                    'dashboards': { m1: 'flag_storytelling_dashboards', m2: 'dashboard_and_storytelling_skills' }
                };

                window.SAS_DATA.triAxial.forEach(item => {
                    const mapping = keyMap[item.id];
                    if (mapping) {
                        // Bind Paid (Axis 2: Market Cumulative Logit Model 1)
                        const m1_info = m1_coefs[mapping.m1];
                        if (m1_info) {
                            item.paidOR = m1_info.odds_ratio;
                            item.paidCILower = m1_info.ci_lower;
                            item.paidCIUpper = m1_info.ci_upper;
                        }
                        // Bind Rewarded (Axis 3: JDS Promotion Logistic Model 2 + BCa Bootstrap)
                        const m2_info = m2_skills[mapping.m2];
                        if (m2_info) {
                            item.rewardedOR = m2_info.odds_ratio;
                            item.rewardedCILower = m2_info.bca_ci_lower;
                            item.rewardedCIUpper = m2_info.bca_ci_upper;
                            item.rankRewardedDrawsPct = m2_info.rank1_bootstrap_pct;
                        }
                    }
                });
                console.log('[ModelOutputs] Injected live trained odds ratios into SAS_DATA.triAxial');

                if (window.SASVisualizer && typeof window.SASVisualizer.renderForestPlot === 'function') {
                    const activeMetric = window.SAS_APP_STATE?.forestMetric || 'paid';
                    window.SASVisualizer.renderForestPlot('forest-plot-container', activeMetric);
                }
            }

            console.log('[ModelOutputs] Loaded real model outputs:', Object.keys(this.data));
            return true;
        } catch (e) {
            console.warn('[ModelOutputs] Could not load model_outputs.json:', e);
            return false;
        }
    },

    /**
     * Renders the real Model Metrics KPI section on a given tab
     */
    renderModelMetrics(containerId) {
        const container = document.getElementById(containerId);
        if (!container || !this.loaded) return;

        const m2 = this.data.model2_jds_hike;
        const m3 = this.data.model3_sds_leakage;

        container.innerHTML = `
            <div class="grid-cols-4" style="margin-bottom:20px;">
                <div class="kpi-card accent-cyan">
                    <div class="kpi-label">JDS Hike Model AUC (Train)</div>
                    <div class="kpi-value">${m2.model_metrics.train_auc.toFixed(4)}</div>
                    <div class="kpi-subtext">Logistic Regression on ${m2.n_observations} juniors</div>
                </div>
                <div class="kpi-card accent-purple">
                    <div class="kpi-label">JDS 5-Fold CV AUC</div>
                    <div class="kpi-value">${m2.model_metrics.cv_5fold_auc_mean.toFixed(4)}</div>
                    <div class="kpi-subtext">&plusmn; ${m2.model_metrics.cv_5fold_auc_std.toFixed(4)} (Stratified K-Fold)</div>
                </div>
                <div class="kpi-card accent-orange">
                    <div class="kpi-label">SDS RF AUC (Leakage)</div>
                    <div class="kpi-value">${m3.random_forest.auc.toFixed(4)}</div>
                    <div class="kpi-subtext">${m3.random_forest.leakage_detected ? '⚠️ LEAKAGE CONFIRMED' : 'No leakage'}</div>
                </div>
                <div class="kpi-card accent-green">
                    <div class="kpi-label">Bootstrap Draws Completed</div>
                    <div class="kpi-value">${m2.successful_draws.toLocaleString()}</div>
                    <div class="kpi-subtext">BCa Confidence Intervals (out of ${m2.bootstrap_draws})</div>
                </div>
            </div>
        `;
    },

    /**
     * Renders real JDS sample predictions table
     */
    renderSamplePredictions(containerId) {
        const container = document.getElementById(containerId);
        if (!container || !this.loaded) return;

        const preds = this.data.model2_jds_hike.sample_predictions;

        let html = `
            <table class="sas-table">
                <thead>
                    <tr>
                        <th>Employee ID</th>
                        <th>Big Data</th>
                        <th>Maths</th>
                        <th>Coding</th>
                        <th>AI/ML</th>
                        <th>Dashboards</th>
                        <th>P(High Hike)</th>
                        <th>Predicted</th>
                        <th>Actual</th>
                        <th>Result</th>
                    </tr>
                </thead>
                <tbody>
        `;

        preds.forEach(p => {
            const correct = p.correct;
            html += `
                <tr>
                    <td class="font-bold">#${p.emp_id}</td>
                    <td>${p.scores.big_data.toFixed(1)}</td>
                    <td>${p.scores.maths_stats.toFixed(1)}</td>
                    <td>${p.scores.coding.toFixed(1)}</td>
                    <td>${p.scores.ai_ml.toFixed(1)}</td>
                    <td>${p.scores.dashboards.toFixed(1)}</td>
                    <td class="font-semibold ${p.predicted_high_hike_prob > 0.5 ? 'text-blue' : ''}">${(p.predicted_high_hike_prob * 100).toFixed(1)}%</td>
                    <td><span class="sas-badge ${p.predicted_label ? 'badge-success' : 'badge-warning'}">${p.predicted_label ? 'HIGH' : 'LOW'}</span></td>
                    <td><span class="sas-badge ${p.actual_label ? 'badge-info' : 'badge-warning'}">${p.actual_label ? 'HIGH' : 'LOW'}</span></td>
                    <td>${correct ? '<span class="sas-badge badge-success">✓ Correct</span>' : '<span class="sas-badge badge-danger">✗ Miss</span>'}</td>
                </tr>
            `;
        });

        html += `</tbody></table>`;
        container.innerHTML = html;
    },

    /**
     * Renders persona predictions from the real trained model
     */
    renderPersonaPredictions(containerId) {
        const container = document.getElementById(containerId);
        if (!container || !this.loaded) return;

        const pp = this.data.persona_predictions;

        let html = `
            <table class="sas-table">
                <thead>
                    <tr>
                        <th>Persona</th>
                        <th>Big Data</th>
                        <th>Maths</th>
                        <th>Coding</th>
                        <th>AI/ML</th>
                        <th>Dashboards</th>
                        <th>P(High Hike)</th>
                        <th>Model Prediction</th>
                        <th>Confidence</th>
                    </tr>
                </thead>
                <tbody>
        `;

        for (const [name, p] of Object.entries(pp)) {
            html += `
                <tr>
                    <td class="font-bold text-navy" style="text-transform:capitalize;">${name}</td>
                    <td>${p.scores.big_data_skills.toFixed(1)}</td>
                    <td>${p.scores['maths-stats_skills'].toFixed(1)}</td>
                    <td>${p.scores.coding_skills.toFixed(1)}</td>
                    <td>${p.scores.ai_and_ml_skills.toFixed(1)}</td>
                    <td>${p.scores.dashboard_and_storytelling_skills.toFixed(1)}</td>
                    <td class="font-semibold text-blue">${(p.high_hike_probability * 100).toFixed(1)}%</td>
                    <td><span class="sas-badge ${p.predicted_high_hike ? 'badge-success' : 'badge-danger'}">${p.predicted_high_hike ? 'HIGH HIKE ✓' : 'LOW HIKE'}</span></td>
                    <td>${(p.model_confidence * 100).toFixed(1)}%</td>
                </tr>
            `;
        }

        html += `</tbody></table>`;
        container.innerHTML = html;
    },

    /**
     * Renders ROC curve as SVG
     */
    renderROCCurve(containerId, model = 'jds') {
        const container = document.getElementById(containerId);
        if (!container || !this.loaded) return;

        if (model === 'jds' && window.SASVisualizer && typeof window.SASVisualizer.renderInteractiveROC === 'function') {
            window.SASVisualizer.renderInteractiveROC(containerId, 'confusion-matrix-jds', 'jds');
            return;
        }

        const points = model === 'jds'
            ? this.data.model2_jds_hike.roc_curve_points
            : this.data.model3_sds_leakage.roc_curve_points;

        const auc = model === 'jds'
            ? this.data.model2_jds_hike.model_metrics.train_auc
            : this.data.model3_sds_leakage.logistic_ocean.auc;

        const width = 360, height = 340;
        const margin = { top: 30, right: 20, bottom: 45, left: 50 };
        const pw = width - margin.left - margin.right;
        const ph = height - margin.top - margin.bottom;

        function x(v) { return margin.left + v * pw; }
        function y(v) { return margin.top + (1 - v) * ph; }

        let svg = `<svg viewBox="0 0 ${width} ${height}" style="width:100%; height:auto;">`;

        // Grid
        for (let g = 0; g <= 1.0; g += 0.2) {
            svg += `<line x1="${x(g)}" y1="${y(0)}" x2="${x(g)}" y2="${y(1)}" stroke="#E2E8F0" />`;
            svg += `<line x1="${x(0)}" y1="${y(g)}" x2="${x(1)}" y2="${y(g)}" stroke="#E2E8F0" />`;
            svg += `<text x="${x(g)}" y="${y(0) + 15}" text-anchor="middle" fill="#718096" font-size="10">${g.toFixed(1)}</text>`;
            svg += `<text x="${x(0) - 8}" y="${y(g) + 4}" text-anchor="end" fill="#718096" font-size="10">${g.toFixed(1)}</text>`;
        }

        // Diagonal (random classifier)
        svg += `<line x1="${x(0)}" y1="${y(0)}" x2="${x(1)}" y2="${y(1)}" stroke="#CBD5E1" stroke-width="1" stroke-dasharray="4,4" />`;

        // ROC Curve
        let pathD = '';
        points.forEach((pt, i) => {
            const cmd = i === 0 ? 'M' : 'L';
            pathD += `${cmd} ${x(pt.fpr)},${y(pt.tpr)} `;
        });
        const color = model === 'jds' ? '#005A9C' : '#6D28D9';
        svg += `<path d="${pathD}" fill="none" stroke="${color}" stroke-width="2.5" />`;

        // AUC label
        svg += `<text x="${x(0.55)}" y="${y(0.25)}" fill="${color}" font-size="14" font-weight="bold">AUC = ${auc.toFixed(4)}</text>`;

        // Axis labels
        svg += `<text x="${width / 2}" y="${height - 4}" text-anchor="middle" fill="#4A5568" font-size="11">False Positive Rate</text>`;
        svg += `<text x="12" y="${height / 2}" text-anchor="middle" fill="#4A5568" font-size="11" transform="rotate(-90, 12, ${height / 2})">True Positive Rate</text>`;

        // Title
        const title = model === 'jds' ? 'JDS Junior Hike Model ROC' : 'SDS OCEAN Logistic ROC';
        svg += `<text x="${width / 2}" y="16" text-anchor="middle" fill="#0F2C59" font-size="13" font-weight="bold">${title}</text>`;

        svg += `</svg>`;
        container.innerHTML = svg;
    },

    /**
     * Renders confusion matrix
     */
    renderConfusionMatrix(containerId) {
        const container = document.getElementById(containerId);
        if (!container || !this.loaded) return;

        const cm = this.data.model2_jds_hike.model_metrics.confusion_matrix;
        const tn = cm[0][0], fp = cm[0][1], fn = cm[1][0], tp = cm[1][1];
        const total = tn + fp + fn + tp;

        container.innerHTML = `
            <div style="display:flex; flex-direction:column; align-items:center;">
                <div style="font-size:13px; font-weight:700; color:#0F2C59; margin-bottom:10px;">JDS Hike Model Confusion Matrix (n=${total})</div>
                <table style="border-collapse:collapse; text-align:center; font-size:13px;">
                    <tr>
                        <td style="padding:6px 12px;"></td>
                        <td style="padding:6px 12px; font-weight:700; color:#005A9C;">Pred: LOW</td>
                        <td style="padding:6px 12px; font-weight:700; color:#005A9C;">Pred: HIGH</td>
                    </tr>
                    <tr>
                        <td style="padding:6px 12px; font-weight:700; color:#6D28D9;">Actual: LOW</td>
                        <td style="padding:6px 12px; background:#DEF7EC; font-weight:700; color:#03543F; border:1px solid #CBD5E1;">${tn} (TN)</td>
                        <td style="padding:6px 12px; background:#FDE8E8; font-weight:700; color:#9B1C1C; border:1px solid #CBD5E1;">${fp} (FP)</td>
                    </tr>
                    <tr>
                        <td style="padding:6px 12px; font-weight:700; color:#6D28D9;">Actual: HIGH</td>
                        <td style="padding:6px 12px; background:#FDE8E8; font-weight:700; color:#9B1C1C; border:1px solid #CBD5E1;">${fn} (FN)</td>
                        <td style="padding:6px 12px; background:#DEF7EC; font-weight:700; color:#03543F; border:1px solid #CBD5E1;">${tp} (TP)</td>
                    </tr>
                </table>
            </div>
        `;
    },

    /**
     * Renders SDS trait means by success group as bar chart
     */
    /**
     * Renders SDS trait means by success group, with dynamic candidate overlay if active
     */
    renderTraitComparison(containerId, candidate = null) {
        const container = document.getElementById(containerId);
        if (!container || !this.loaded) return;

        const cand = candidate || window.SAS_APP_STATE?.activeCandidate;
        const traits = this.data.model3_sds_leakage.trait_means_by_group;
        const traitNames = {
            'conscientiousness': 'Conscientiousness',
            'openness_to_experience': 'Openness',
            'extraversion': 'Extraversion',
            'agreeableness': 'Agreeableness',
            'neuroticism': 'Neuroticism'
        };

        // If candidate is present, resolve their Big Five OCEAN traits (0-68 scale)
        let candOcean = null;
        if (cand) {
            const raw = cand.ocean_traits || cand.predictions?.inputs?.ocean_traits;
            if (raw) {
                candOcean = {
                    'conscientiousness': parseFloat(raw.conscientiousness || 45.0),
                    'openness_to_experience': parseFloat(raw.openness_to_experience || raw.openness || 42.0),
                    'extraversion': parseFloat(raw.extraversion || 44.0),
                    'agreeableness': parseFloat(raw.agreeableness || 45.0),
                    'neuroticism': parseFloat(raw.neuroticism || 35.0)
                };
            } else if (cand.scores) {
                const s = cand.scores;
                const exp = parseFloat(cand.exp || 1.0);
                candOcean = {
                    'conscientiousness': Math.min(66.0, Math.max(25.0, 42.0 + (s.core_coding >= 4.0 ? 5.5 : 0) + (s.maths_stats >= 4.0 ? 5.0 : 0) + exp * 1.5)),
                    'openness_to_experience': Math.min(65.0, Math.max(24.0, 39.0 + (s.ai_ml >= 3.5 ? 6.5 : 0) + (s.big_data >= 3.5 ? 4.0 : 0))),
                    'extraversion': Math.min(67.0, Math.max(22.0, 38.0 + (s.dashboards >= 3.5 ? 7.5 : 0) + Math.min(5.0, exp * 1.2))),
                    'agreeableness': Math.min(68.0, Math.max(26.0, 42.0 + (s.dashboards >= 3.0 ? 4.0 : 0))),
                    'neuroticism': Math.max(20.0, Math.min(50.0, 36.5 - (s.core_coding >= 4.0 ? 3.0 : 0) - (exp >= 2.0 ? 1.5 : 0)))
                };
            }
        }

        let html = '';

        if (cand && candOcean) {
            html += `
                <div style="background:#EBF3FA; border-left:4px solid #005A9C; border-radius:4px; padding:8px 12px; margin-bottom:14px; display:flex; justify-content:space-between; align-items:center;">
                    <div>
                        <strong style="color:#0F2C59; font-size:12px;">Active Candidate Alignment: ${cand.name}</strong>
                        <div style="font-size:11px; color:#56687A;">Inferred Big Five Traits (0-68 scale) benchmarked against Senior Data Scientist cohorts</div>
                    </div>
                    <span class="sas-badge badge-primary" style="font-size:10px;">CANDIDATE SYNCED</span>
                </div>
            `;
        }

        html += '<div style="display:flex; flex-direction:column; gap:14px;">';

        const orderedKeys = ['conscientiousness', 'openness_to_experience', 'extraversion', 'agreeableness', 'neuroticism'];

        orderedKeys.forEach(key => {
            const data = traits[key];
            if (!data) return;

            const maxVal = 68;
            const highPct = (data.high_success_mean / maxVal * 100).toFixed(1);
            const lowPct = (data.low_success_mean / maxVal * 100).toFixed(1);
            const diff = data.difference > 0 ? `+${data.difference.toFixed(1)}` : data.difference.toFixed(1);

            if (cand && candOcean) {
                const cVal = candOcean[key] || 40.0;
                const cPct = (cVal / maxVal * 100).toFixed(1);
                const gapToHigh = cVal - data.high_success_mean;
                const isAligned = Math.abs(gapToHigh) <= 5.0 || (key !== 'neuroticism' && cVal >= data.high_success_mean);
                const statusColor = isAligned ? '#059669' : (gapToHigh < -10.0 ? '#DC2626' : '#D97706');
                const statusText = isAligned ? 'Aligned with High Success' : (gapToHigh < -10.0 ? 'Development Gap' : 'Moderate Alignment');

                html += `
                    <div>
                        <div style="display:flex; justify-content:space-between; font-size:12px; font-weight:700; margin-bottom:4px;">
                            <span style="color:#0F2C59;">${traitNames[key] || key}</span>
                            <span style="color:${statusColor}; font-size:11px;">Candidate: <strong>${cVal.toFixed(1)}</strong> (${statusText})</span>
                        </div>
                        <div style="display:flex; gap:8px; align-items:center;">
                            <!-- Candidate Bar (Vivid Cyan/Blue) -->
                            <div style="flex:1.2;">
                                <div style="background:#E2E8F0; height:8px; border-radius:4px; overflow:hidden; margin-bottom:2px;">
                                    <div style="width:${cPct}%; height:100%; background:linear-gradient(90deg, #005A9C 0%, #00A3E0 100%);"></div>
                                </div>
                                <div style="font-size:10px; color:#005A9C; font-weight:700;">Candidate: ${cVal.toFixed(1)}</div>
                            </div>
                            <!-- High Success Benchmark (Green) -->
                            <div style="flex:1;">
                                <div style="background:#E2E8F0; height:8px; border-radius:4px; overflow:hidden; margin-bottom:2px;">
                                    <div style="width:${highPct}%; height:100%; background:#059669;"></div>
                                </div>
                                <div style="font-size:10px; color:#059669; font-weight:600;">High: ${data.high_success_mean}</div>
                            </div>
                            <!-- Low Success Benchmark (Red) -->
                            <div style="flex:1;">
                                <div style="background:#E2E8F0; height:8px; border-radius:4px; overflow:hidden; margin-bottom:2px;">
                                    <div style="width:${lowPct}%; height:100%; background:#DC2626;"></div>
                                </div>
                                <div style="font-size:10px; color:#DC2626; font-weight:600;">Low: ${data.low_success_mean}</div>
                            </div>
                        </div>
                    </div>
                `;
            } else {
                html += `
                    <div>
                        <div style="display:flex; justify-content:space-between; font-size:12px; font-weight:600; margin-bottom:4px;">
                            <span>${traitNames[key] || key}</span>
                            <span style="color:${data.difference > 0 ? '#059669' : '#DC2626'}">${diff} gap</span>
                        </div>
                        <div style="display:flex; gap:6px; align-items:center;">
                            <div style="flex:1;">
                                <div style="background:#E2E8F0; height:8px; border-radius:4px; overflow:hidden; margin-bottom:2px;">
                                    <div style="width:${highPct}%; height:100%; background:#059669;"></div>
                                </div>
                                <div style="font-size:10px; color:#64748B;">High Success: ${data.high_success_mean}</div>
                            </div>
                            <div style="flex:1;">
                                <div style="background:#E2E8F0; height:8px; border-radius:4px; overflow:hidden; margin-bottom:2px;">
                                    <div style="width:${lowPct}%; height:100%; background:#DC2626;"></div>
                                </div>
                                <div style="font-size:10px; color:#64748B;">Low Success: ${data.low_success_mean}</div>
                            </div>
                        </div>
                    </div>
                `;
            }
        });

        html += '</div>';

        // Add Legend
        if (cand && candOcean) {
            html += `
                <div style="display:flex; justify-content:center; gap:16px; margin-top:14px; font-size:11px; color:#475569; border-top:1px solid #E2E8F0; padding-top:10px;">
                    <span style="display:inline-flex; align-items:center; gap:5px;">
                        <span style="width:12px; height:6px; background:#005A9C; border-radius:2px;"></span> Candidate Profile
                    </span>
                    <span style="display:inline-flex; align-items:center; gap:5px;">
                        <span style="width:12px; height:6px; background:#059669; border-radius:2px;"></span> High-Success Group (n=68)
                    </span>
                    <span style="display:inline-flex; align-items:center; gap:5px;">
                        <span style="width:12px; height:6px; background:#DC2626; border-radius:2px;"></span> Low-Success Group (n=84)
                    </span>
                </div>
            `;
        }

        container.innerHTML = html;
    },

    /**
     * Live Model Inference Engine using exact weights trained from Joblib:
     * - Model 1: Ordinal Logistic Regression on 15,841 jobs (Salary Bands)
     * - Model 2: JDS Logistic Regression on 137 juniors (High Hike > 25%)
     * - Model 3: SDS OCEAN Logistic Regression on 152 seniors
     */
    predictCandidate(inputs) {
        const bd = parseFloat(inputs.big_data || 3.0);
        const ms = parseFloat(inputs.maths || 3.0);
        const cc = parseFloat(inputs.coding || 3.0);
        const am = parseFloat(inputs.ai_ml || 3.0);
        const db = parseFloat(inputs.dashboards || 3.0);
        const exp = parseFloat(inputs.experience_yrs || 0.0);
        const metro = (inputs.metro || 'bengaluru').toLowerCase();

        // Model 1: Ordinal Logistic
        const flag_bd = bd >= 3.0 ? 1 : 0;
        const flag_ms = ms >= 3.0 ? 1 : 0;
        const flag_cc = cc >= 3.0 ? 1 : 0;
        const flag_am = am >= 3.0 ? 1 : 0;
        const flag_db = db >= 3.0 ? 1 : 0;
        const metro_bg = (metro === 'bengaluru' || metro === 'bangalore') ? 1 : 0;
        const metro_mb = metro === 'mumbai' ? 1 : 0;
        const metro_dl = (metro === 'delhi' || metro === 'delhi_ncr') ? 1 : 0;

        const eta = 0.292682 * flag_bd +
                    0.624449 * flag_ms +
                    0.343929 * flag_cc +
                    0.639531 * flag_am +
                    0.151155 * flag_db +
                    0.483355 * exp +
                    0.464117 * metro_bg +
                    0.546013 * metro_mb +
                    0.540258 * metro_dl;

        const c0 = 1.107642;
        const c1 = c0 + Math.exp(0.140817);
        const c2 = c1 + Math.exp(0.175822);
        const c3 = c2 + Math.exp(0.428763);
        const c4 = c3 + Math.exp(0.854158);
        const cuts = [c0, c1, c2, c3, c4];

        const cum = cuts.map(c => 1.0 / (1.0 + Math.exp(-(c - eta))));
        const bands = ['0to3 LPA', '3to6 LPA', '6to10 LPA', '10to15 LPA', '15to25 LPA', '25to50 LPA'];
        const rawProbs = [
            cum[0],
            cum[1] - cum[0],
            cum[2] - cum[1],
            cum[3] - cum[2],
            cum[4] - cum[3],
            1.0 - cum[4]
        ];
        const sumP = rawProbs.reduce((acc, b) => acc + Math.max(0, b), 0);
        const probs = rawProbs.map(p => Math.max(0, p) / sumP);
        const maxPIdx = probs.indexOf(Math.max(...probs));
        const midpoints = [1.5, 4.5, 8.0, 12.5, 20.0, 37.5];
        const expectedSalaryLpa = probs.reduce((acc, p, i) => acc + p * midpoints[i], 0);

        // Model 2: JDS Logistic (joblib weights)
        const z2 = -24.931455 +
                   0.970367 * bd +
                   1.671769 * ms +
                   0.621068 * cc +
                   1.263628 * am +
                   1.236040 * db;
        const hikeProb = 1.0 / (1.0 + Math.exp(-z2));
        const isHighHike = hikeProb >= 0.5;

        // Model 3: SDS OCEAN Logistic
        const n = inputs.ocean?.neuroticism || 32.0;
        const e = inputs.ocean?.extraversion || 38.0;
        const o = inputs.ocean?.openness || 37.0;
        const a = inputs.ocean?.agreeableness || 36.0;
        const c = inputs.ocean?.conscientiousness || 44.0;
        const z3 = -26.184771 +
                   0.072731 * n +
                   0.063377 * e +
                   0.213767 * o +
                   0.049224 * a +
                   0.209610 * c;
        const seniorProb = 1.0 / (1.0 + Math.exp(-z3));

        const foundationDeficit = cc < 2.0;
        const synergyUnlocked = cc >= 3.5 && db >= 3.5;

        return {
            model1: {
                mostLikelyBand: bands[maxPIdx],
                expectedSalaryLpa: expectedSalaryLpa.toFixed(1),
                probabilities: bands.map((b, i) => ({ band: b, prob: probs[i] }))
            },
            model2: {
                hikeProb: hikeProb,
                isHighHike: isHighHike,
                foundationDeficit: foundationDeficit,
                synergyUnlocked: synergyUnlocked,
                confidence: (Math.max(hikeProb, 1.0 - hikeProb) * 100).toFixed(1)
            },
            model3: {
                seniorProb: seniorProb,
                conscientiousness: c
            }
        };
    },

    /**
     * Renders Live Prediction Card on container
     */
    renderLivePrediction(containerId, inputs) {
        const container = document.getElementById(containerId);
        if (!container) return;

        const pred = this.predictCandidate(inputs);
        const m1 = pred.model1;
        const m2 = pred.model2;
        const m3 = pred.model3;

        const hikePct = (m2.hikeProb * 100).toFixed(1);
        const seniorPct = (m3.seniorProb * 100).toFixed(1);

        let html = `
            <div class="live-prediction-banner" style="background:#FFFFFF; border:2px solid #005A9C; border-radius:8px; padding:20px; box-shadow:0 4px 12px rgba(0,90,156,0.1); margin-bottom:20px;">
                <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:16px; border-bottom:1px solid #E2E8F0; padding-bottom:12px;">
                    <div>
                        <span class="sas-badge badge-primary" style="font-size:11px; margin-right:8px;">JOBLIB INFERENCE ENGINE</span>
                        <h3 style="display:inline; font-size:16px; font-weight:800; color:#0F2C59;">Live Candidate Evaluation (3 Models Combined)</h3>
                    </div>
                    <div>
                        ${m2.foundationDeficit 
                            ? '<span class="sas-badge badge-danger" style="font-size:13px; font-weight:800;">FORMAL ABSTENTION (Coding &lt; 2.0)</span>'
                            : (m2.isHighHike 
                                ? '<span class="sas-badge badge-success" style="font-size:13px; font-weight:800;">HIGH HIKE PREDICTED (&gt;25%)</span>' 
                                : '<span class="sas-badge badge-warning" style="font-size:13px; font-weight:800;">LOW HIKE PREDICTED (&le;25%)</span>')}
                    </div>
                </div>

                <div class="grid-cols-3" style="gap:16px;">
                    <!-- Model 1 Card -->
                    <div style="background:#F8FAFC; border:1px solid #CBD5E1; border-radius:6px; padding:14px;">
                        <div style="font-size:11px; font-weight:700; color:#64748B; text-transform:uppercase;">Model 1: Market Compensation</div>
                        <div style="font-size:18px; font-weight:800; color:#005A9C; margin:6px 0 2px 0;">${m1.mostLikelyBand}</div>
                        <div style="font-size:12px; color:#475569;">Expected Midpoint: <strong>Rs. ${m1.expectedSalaryLpa} LPA</strong></div>
                        <div style="margin-top:10px;">
                            <div style="font-size:10px; color:#64748B; margin-bottom:4px; font-weight:600;">Salary Band Probabilities:</div>
                            ${m1.probabilities.map(p => `
                                <div style="display:flex; justify-content:space-between; font-size:10px; margin-bottom:2px;">
                                    <span>${p.band}</span>
                                    <span style="font-weight:700;">${(p.prob*100).toFixed(0)}%</span>
                                </div>
                                <div style="background:#E2E8F0; height:4px; border-radius:2px; margin-bottom:4px; overflow:hidden;">
                                    <div style="background:${p.prob > 0.25 ? '#005A9C' : '#94A3B8'}; height:100%; width:${(p.prob*100).toFixed(0)}%;"></div>
                                </div>
                            `).join('')}
                        </div>
                    </div>

                    <!-- Model 2 Card -->
                    <div style="background:#F8FAFC; border:1px solid #CBD5E1; border-radius:6px; padding:14px;">
                        <div style="font-size:11px; font-weight:700; color:#64748B; text-transform:uppercase;">Model 2: Junior Hike Velocity</div>
                        <div style="font-size:24px; font-weight:800; color:${m2.hikeProb > 0.5 ? '#059669' : '#DC2626'}; margin:4px 0;">${hikePct}%</div>
                        <div style="font-size:12px; color:#475569;">Model Confidence: <strong>${m2.confidence}%</strong></div>
                        <div style="background:#E2E8F0; height:8px; border-radius:4px; margin:10px 0 12px 0; overflow:hidden;">
                            <div style="background:${m2.hikeProb > 0.5 ? '#059669' : '#DC2626'}; height:100%; width:${hikePct}%; transition:width 0.3s ease;"></div>
                        </div>
                        <div style="font-size:11px; display:flex; flex-direction:column; gap:6px;">
                            <div>
                                ${m2.synergyUnlocked 
                                    ? '<span style="color:#059669; font-weight:700;">⚡ Coding &times; Story Synergy Unlocked (+2.18x)</span>' 
                                    : '<span style="color:#64748B;">Synergy: Baseline (Needs Coding &ge; 3.5 & Story &ge; 3.5)</span>'}
                            </div>
                            <div>
                                ${m2.foundationDeficit 
                                    ? '<span style="color:#DC2626; font-weight:700;">⚠️ Baseline Deficit: Coding &lt; 2.0 (Kabir Condition)</span>' 
                                    : '<span style="color:#059669; font-weight:600;">✓ Foundation Gatekeeper Satisfied</span>'}
                            </div>
                        </div>
                    </div>

                    <!-- Model 3 Card -->
                    <div style="background:#F8FAFC; border:1px solid #CBD5E1; border-radius:6px; padding:14px;">
                        <div style="font-size:11px; font-weight:700; color:#64748B; text-transform:uppercase;">Model 3: Senior Advancement</div>
                        <div style="font-size:24px; font-weight:800; color:#6D28D9; margin:4px 0;">${seniorPct}%</div>
                        <div style="font-size:12px; color:#475569;">Conscientiousness: <strong>${m3.conscientiousness} / 68</strong></div>
                        <div style="background:#E2E8F0; height:8px; border-radius:4px; margin:10px 0 12px 0; overflow:hidden;">
                            <div style="background:#6D28D9; height:100%; width:${seniorPct}%; transition:width 0.3s ease;"></div>
                        </div>
                        <div style="font-size:11px; color:#475569; line-height:1.4;">
                            Senior Advancement is governed by executive conscientiousness and trust rather than incremental junior math velocity.
                        </div>
                    </div>
                </div>
            </div>
        `;
        container.innerHTML = html;
    }
};

// Auto-load on window
if (typeof window !== "undefined") {
    window.ModelOutputs = ModelOutputs;
}
